const wrapper = $input.first().json ?? {};
const event = wrapper.event;
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isId = (value) => typeof value === 'string' && value.length >= 1 && value.length <= 64;
const invalid = {
  valid: false,
  eventId: isId(event?.eventId) ? event.eventId : '',
  organizationId: isId(event?.organizationId) ? event.organizationId : '',
  runId: isId(event?.runId) ? event.runId : '',
  errorCode: 'invalid_handoff_event',
  errorContext: 'handoff',
};
if (!isObject(wrapper) || !isObject(event) || event.type !== 'conversation.handoff_requested' || !isId(event.eventId) || !isId(event.organizationId) || !isId(event.runId) || !isObject(event.payload)) {
  return [{ json: invalid }];
}
const payload = event.payload;
if (payload.eventId !== event.eventId || payload.organizationId !== event.organizationId || !isId(payload.conversationId)) {
  return [{ json: invalid }];
}
const actionTimestamp = Date.now();
const actionBody = JSON.stringify({
  eventId: event.eventId,
  organizationId: event.organizationId,
});
return [{ json: {
  valid: true,
  eventId: event.eventId,
  organizationId: event.organizationId,
  runId: event.runId,
  actionTimestamp: String(actionTimestamp),
  actionBody,
} }];

const source = $('Prepare handoff action').first().json;
const response = $input.first().json ?? {};
const statusCode = Number(response.statusCode);
const body = response.body !== null && typeof response.body === 'object' && !Array.isArray(response.body) ? response.body : {};
const state = typeof body.state === 'string' ? body.state : typeof body.error === 'string' ? body.error : '';
if (statusCode === 200 && ['success', 'already_sent'].includes(state)) {
  return [{ json: {
    decision: 'success',
    eventId: source.eventId,
    organizationId: source.organizationId,
    runId: source.runId,
    actionState: state,
    duplicate: state === 'already_sent' || body.duplicate === true,
  } }];
}
if ((statusCode === 200 || statusCode === 409) && ['in_progress', 'not_executable'].includes(state)) {
  return [{ json: {
    decision: 'no_callback',
    eventId: source.eventId,
    organizationId: source.organizationId,
    runId: source.runId,
    actionState: state,
  } }];
}
const confirmedSendFailure = statusCode === 502 && body.error === 'send_failed';
const transportAmbiguous = !Number.isInteger(statusCode)
  || statusCode < 100
  || [408, 425, 429].includes(statusCode)
  || statusCode >= 500;
if (transportAmbiguous && !confirmedSendFailure) {
  return [{ json: {
    decision: 'no_callback',
    eventId: source.eventId,
    organizationId: source.organizationId,
    runId: source.runId,
    actionState: 'transport_ambiguous',
  } }];
}
const errorCode = statusCode === 401
  ? 'handoff_action_auth_rejected'
  : statusCode === 404
    ? 'handoff_action_not_found'
    : statusCode === 409
      ? 'handoff_action_conflict'
      : statusCode === 429
        ? 'handoff_action_rate_limited'
        : Number.isInteger(statusCode) && statusCode >= 400 && statusCode < 500
          ? 'handoff_action_rejected'
          : 'handoff_action_unavailable';
return [{ json: {
  decision: 'failure',
  eventId: source.eventId,
  organizationId: source.organizationId,
  runId: source.runId,
  errorCode,
  errorContext: 'handoff',
} }];

const result = $input.first().json;
const callbackTimestamp = Date.now();
const callbackBody = JSON.stringify({
  eventId: result.eventId,
  organizationId: result.organizationId,
  runId: result.runId,
  timestamp: callbackTimestamp,
  status: 'succeeded',
  externalExecutionId: String($execution.id),
  responseMeta: {
    workflow: 'vantix-handoff-alert',
    actionState: result.actionState,
    duplicate: result.duplicate === true,
  },
});
return [{ json: { callbackBody, callbackTimestamp: String(callbackTimestamp) } }];
